-- Intent: Add summary counts (ready_to_sell_count, incomplete_count, inactive_count) to catalog.search_products RPC
-- Touches: search_products
-- Promoted from _drafts/catalog_search_products_summary_counts.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

drop function if exists catalog.search_products(
  uuid, text, text[], text, boolean, int, int, jsonb, text
);

create or replace function catalog.search_products(
  p_tenant_id uuid,
  p_keyword text default null,
  p_business_statuses text[] default array['active']::text[],
  p_readiness_filter text default null,
  p_include_soft_deleted boolean default false,
  p_limit int default 50,
  p_offset int default 0,
  p_custom_field_filters jsonb default '[]'::jsonb,
  p_sort_order text default 'updated_at_desc'
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  primary_image_url text,
  business_status text,
  is_soft_deleted boolean,
  base_unit_name text,
  stock_qty numeric,
  list_price numeric,
  floor_price numeric,
  list_price_before_vat numeric,
  floor_price_before_vat numeric,
  list_price_after_vat numeric,
  floor_price_after_vat numeric,
  updated_at timestamptz,
  has_base_unit boolean,
  has_images boolean,
  has_stock boolean,
  has_base_price boolean,
  has_price_band boolean,
  has_required_custom_fields boolean,
  stock_mode text,
  base_price_mode text,
  custom_field_values jsonb,
  total_count bigint,
  ready_to_sell_count bigint,
  incomplete_count bigint,
  inactive_count bigint
)
language plpgsql
security definer
set search_path = catalog, inventory, iam, extensions, pg_temp
as $$
declare
  v_keyword text;
  v_sku_keyword text;
  v_keyword_unaccented text;
  v_keyword_pattern text;
  v_tsquery tsquery;
  v_sort_order text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  v_keyword := nullif(btrim(coalesce(p_keyword, '')), '');
  v_sku_keyword := catalog._normalize_product_sku(v_keyword);
  v_keyword_unaccented := nullif(
    lower(btrim(catalog.unaccent_immutable(coalesce(v_keyword, '')))),
    ''
  );
  v_keyword_pattern := case
    when v_keyword_unaccented is null then null
    else '%'
      || replace(
        replace(replace(v_keyword_unaccented, '\', '\\'), '%', '\%'),
        '_',
        '\_'
      )
      || '%'
  end;

  if v_keyword_unaccented is null then
    v_tsquery := null;
  else
    v_tsquery := websearch_to_tsquery('simple', v_keyword_unaccented);
    if numnode(v_tsquery) = 0 then
      v_tsquery := null;
    end if;
  end if;

  v_sort_order := case
    when p_sort_order = 'relevance_desc' then 'relevance_desc'
    else 'updated_at_desc'
  end;

  return query
  with matched as (
    select
      p.id,
      p.name,
      p.trade_name,
      p.sku,
      p.barcode,
      p.search_document,
      p.business_status::text as business_status,
      (p.business_status = 'soft_deleted'::catalog.product_business_status) as is_soft_deleted,
      p.is_ready_to_sell,
      p.updated_at,
      p.fact_has_base_unit,
      p.fact_has_images,
      p.fact_has_base_price,
      p.fact_has_price_band,
      p.fact_has_required_custom_fields,
      p.fact_base_price_mode
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and (
        p_include_soft_deleted
        or p.business_status <> 'soft_deleted'::catalog.product_business_status
        or 'soft_deleted' = any (p_business_statuses)
      )
      and p.business_status::text = any (p_business_statuses)
      and (
        p_readiness_filter is null
        or (p_readiness_filter = 'ready_to_sell' and p.is_ready_to_sell)
        or (p_readiness_filter = 'incomplete' and not p.is_ready_to_sell)
      )
      and (
        v_keyword is null
        or (
          v_keyword_pattern is not null
          and p.search_text like v_keyword_pattern escape '\'
        )
        or (v_sku_keyword is not null and p.sku = v_sku_keyword)
        or (v_keyword is not null and p.barcode = btrim(v_keyword))
        or (
          v_sku_keyword is not null
          and length(v_sku_keyword) >= 1
          and p.sku like v_sku_keyword || '%'
        )
      )
      and catalog._product_matches_custom_field_filters(
        p_tenant_id,
        p.id,
        coalesce(p_custom_field_filters, '[]'::jsonb)
      )
  ),
  ranked as (
    select
      m.*,
      case
        when v_keyword is not null
          and v_sort_order = 'relevance_desc'
          and v_tsquery is not null
        then ts_rank_cd(m.search_document, v_tsquery, 32)
        else null
      end as relevance_rank
    from matched m
  ),
  counted as (
    select
      count(*)::bigint as total_count,
      count(*) filter (where r.business_status = 'active' and r.is_ready_to_sell = true)::bigint as ready_to_sell_count,
      count(*) filter (where r.business_status = 'active' and r.is_ready_to_sell = false)::bigint as incomplete_count,
      count(*) filter (where r.business_status = 'inactive')::bigint as inactive_count
    from ranked r
  ),
  page as (
    select r.*
    from ranked r
    order by
      case when r.business_status = 'active' then 0 else 1 end,
      r.relevance_rank desc nulls last,
      r.updated_at desc,
      r.name asc
    limit greatest(p_limit, 0)
    offset greatest(p_offset, 0)
  ),
  page_stock as materialized (
    select sr.*
    from inventory._product_stock_rows(
      p_tenant_id,
      (select coalesce(array_agg(pg.id), array[]::uuid[]) from page pg)
    ) sr
  )
  select
    pg.id as product_id,
    pg.name,
    pg.trade_name,
    pg.sku,
    pg.barcode,
    (
      select coalesce(i.file_url, i.storage_key)
      from catalog.product_images i
      where i.product_id = pg.id
        and i.tenant_id = p_tenant_id
      order by i.is_primary desc, i.sort_order asc, i.created_at asc
      limit 1
    ) as primary_image_url,
    pg.business_status,
    pg.is_soft_deleted,
    (
      select u.unit_name
      from catalog.product_units u
      where u.product_id = pg.id
        and u.tenant_id = p_tenant_id
        and u.is_base_unit = true
      limit 1
    ) as base_unit_name,
    coalesce(st.available, 0)::numeric as stock_qty,
    (
      select pb.list_price_before_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as list_price,
    (
      select pb.floor_price_before_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as floor_price,
    (
      select pb.list_price_before_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as list_price_before_vat,
    (
      select pb.floor_price_before_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as floor_price_before_vat,
    (
      select pb.list_price_after_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as list_price_after_vat,
    (
      select pb.floor_price_after_vat
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = pg.id
       and bu.is_base_unit = true
      where pb.product_id = pg.id
        and pb.tenant_id = p_tenant_id
        and pb.status = 'active'
        and pb.effective_from <= now()
        and (pb.effective_to is null or pb.effective_to > now())
      limit 1
    ) as floor_price_after_vat,
    pg.updated_at,
    pg.fact_has_base_unit as has_base_unit,
    pg.fact_has_images as has_images,
    (coalesce(st.physical, 0) > 0) as has_stock,
    pg.fact_has_base_price as has_base_price,
    pg.fact_has_price_band as has_price_band,
    pg.fact_has_required_custom_fields as has_required_custom_fields,
    'advanced'::text as stock_mode,
    pg.fact_base_price_mode as base_price_mode,
    catalog._product_custom_field_list_values_json(p_tenant_id, pg.id) as custom_field_values,
    c.total_count,
    c.ready_to_sell_count,
    c.incomplete_count,
    c.inactive_count
  from page pg
  cross join counted c
  left join page_stock st on st.product_id = pg.id
  order by
    case when pg.business_status = 'active' then 0 else 1 end,
    pg.relevance_rank desc nulls last,
    pg.updated_at desc,
    pg.name asc;
end;
$$;

revoke all on function catalog.search_products(
  uuid, text, text[], text, boolean, int, int, jsonb, text
) from public;
grant execute on function catalog.search_products(
  uuid, text, text[], text, boolean, int, int, jsonb, text
) to authenticated;
